\set ON_ERROR_STOP on
begin;
create function pg_temp.reflection_assert(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',message;end if;end$$;
create function pg_temp.reflection_denied(statement text) returns void language plpgsql as $$begin begin execute statement;exception when insufficient_privilege or raise_exception or check_violation then return;end;raise exception 'FAIL: forbidden reflection operation succeeded';end$$;
insert into auth.users(id) values('88888888-8888-4888-8888-888888888888'),('99999999-9999-4999-8999-999999999999'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
insert into public.tasteprint_social_plans(id,creator_id,recipient_id,title,state,details) values('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','88888888-8888-4888-8888-888888888888','99999999-9999-4999-8999-999999999999','Synthetic reflection','scheduled',jsonb_build_object('starts_at',now()-interval '1 day','place','Synthetic room'));
select pg_temp.reflection_assert((select relrowsecurity from pg_class where oid='public.tasteprint_plan_reflections'::regclass),'RLS enabled');
select pg_temp.reflection_assert(not has_table_privilege('authenticated','public.tasteprint_plan_reflections','SELECT'),'no raw feedback access');
select pg_temp.reflection_assert(not has_function_privilege('anon','public.tasteprint_export_my_plan_reflections()','EXECUTE'),'no anonymous feedback export');
set role authenticated;
select set_config('request.jwt.claim.sub','88888888-8888-4888-8888-888888888888',true);
select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'attended','enjoyed','yes');
select pg_temp.reflection_assert(public.tasteprint_read_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1)->>'enjoyment'='enjoyed','own answer persisted');
select pg_temp.reflection_assert(not(public.tasteprint_read_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1)?'actor_id'),'projection excludes identity');
select pg_temp.reflection_denied($q$select * from public.tasteprint_plan_reflections$q$);
select pg_temp.reflection_denied($q$select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',2,'attended','enjoyed','yes')$q$);
select pg_temp.reflection_denied($q$select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'did_not_attend','enjoyed','yes')$q$);
select pg_temp.reflection_denied($q$select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,null,null,null)$q$);
select pg_temp.reflection_denied($q$select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'attended',null,'fake')$q$);
reset role;
update public.tasteprint_social_plans set state='mutual_interest';
set role authenticated;
select set_config('request.jwt.claim.sub','88888888-8888-4888-8888-888888888888',true);
select pg_temp.reflection_denied($q$select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'attended',null,null)$q$);
reset role;
update public.tasteprint_social_plans set state='scheduled';
set role authenticated;
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',true);
select pg_temp.reflection_assert(public.tasteprint_read_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1)='null'::jsonb,'other participant cannot read answer');
select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'attended','mixed','unsure');
select pg_temp.reflection_assert(jsonb_array_length(public.tasteprint_export_my_plan_reflections())=1 and public.tasteprint_export_my_plan_reflections()->0->>'enjoyment'='mixed','export includes own answer only');
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select pg_temp.reflection_assert(public.tasteprint_export_my_plan_reflections()='[]'::jsonb,'nonmember sees no feedback');
select pg_temp.reflection_denied($q$select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'attended',null,null)$q$);
reset role;
update public.tasteprint_social_plans set details=jsonb_set(details,'{starts_at}',to_jsonb((now()+interval '1 day')::text));
set role authenticated;
select set_config('request.jwt.claim.sub','88888888-8888-4888-8888-888888888888',true);
select pg_temp.reflection_denied($q$select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'attended',null,null)$q$);
reset role;
update public.tasteprint_social_plans set details=jsonb_set(details,'{starts_at}',to_jsonb((now()-interval '1 day')::text));
set role authenticated;
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',true);
insert into public.tasteprint_social_blocks values('99999999-9999-4999-8999-999999999999','88888888-8888-4888-8888-888888888888');
select set_config('request.jwt.claim.sub','88888888-8888-4888-8888-888888888888',true);
select pg_temp.reflection_denied($q$select public.tasteprint_save_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'attended',null,null)$q$);
select pg_temp.reflection_assert(jsonb_array_length(public.tasteprint_export_my_plan_reflections())=1,'own export works while blocked');
select pg_temp.reflection_assert(public.tasteprint_delete_my_plan_reflections('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')=1,'own erasure while blocked');
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',true);
select pg_temp.reflection_assert(public.tasteprint_read_my_plan_reflection('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1)->>'enjoyment'='mixed','other private answer preserved');
select public.tasteprint_remove_my_plan_participation('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
select pg_temp.reflection_assert(public.tasteprint_export_my_plan_reflections()='[]'::jsonb,'plan erasure cascades own feedback');
rollback;
\echo 'Reflection SQL PASS: own-only self-reports, no future/unapproved/stale/nonmember writes, blocked export/erasure, preserved other-person answers and cascades.'
